for normal,knock in [(88,31),(76,28)]:
    b.add(c,f'Knockout and rescue {normal}','A constructed plant experiment measures mean root length in otherwise matched lines.'+T(['Line','Mean root length / mm'],[['Unedited control',normal],['Gene-X knockout',knock],['Knockout + functional gene X',normal-3]]),level='ahl',kind='data-based',family='knockout rescue inference',difficulty='hard',parts=[P('Calculate the percentage reduction in mean root length in the knockout relative to the control.',M(f'$({normal}-{knock})/{normal}\\times100$.'),A(f'${num((normal-knock)/normal*100)}\\%$.')),P('Explain how the rescue line strengthens the interpretation.',R('Restoring functional gene X largely restores root length, supporting an effect of lost gene-X function rather than an unrelated difference.')),P('State one limitation of the evidence shown.',A('Accept one: no spread / replicate numbers shown; off-target changes still need checking; only one growth condition / trait is measured.'))]);b.check('root reduction percentage',f'({normal}-{knock})/{normal}*100',(normal-knock)/normal*100)

