b.add(c,'An X-linked recessive allele','A carrier mother has genotype $X^HX^h$ and the father is unaffected, $X^HY$. The recessive allele h causes haemophilia in this simplified pedigree model.',parts=[P('State the probability that a son has haemophilia.',A('$1/2$ of sons.')),P('State the probability that a child of unspecified sex has haemophilia, assuming equal probabilities of male and female births.',A('$1/4$ of all children.')),P('Explain why the father does not pass his X-linked allele to a son.',R('A son receives the father’s Y chromosome and the mother’s X chromosome.'))])
