# Bounded statement-coverage additions after the independent item review.
# These extend existing questions and never alter the frozen vector figures.
def extend(number,*parts):
    q=b.qs[number-1]
    assert q['questionType']!='multiple-choice'
    for prompt,points in parts:
        label=chr(97+len(q['parts']));marks=sum(int(code[1:]) for code,_ in points if code!='AG')
        q['parts'].append({'label':label,'prompt':prompt,'marks':marks})
        q['markScheme'].append({'part':label,'steps':[{'code':code,'text':text} for code,text in points]})
        q['marks']+=marks
    q['verification']['notes']+=' Independently checked statement-coverage subparts added within the existing SL/AHL boundary.'

